<script setup>
import IeltsNavigation from '../components/IeltsNavigation.vue'
import {ref,reactive,onMounted} from 'vue'
import {useRouter} from 'vue-router'
import ielts,{requestKey} from '../api/ielts.js'
const router=useRouter(),papers=ref([]),selected=ref(null),editor=ref(''),note=ref(''),error=ref(''),message=ref(''),busy=ref(false),confirmed=ref(false)
const grant=reactive({userId:null,units:20,requestKey:requestKey()})
async function load(){try{papers.value=(await ielts.adminCatalog()).papers}catch(e){error.value=e.message}}
async function edit(id){try{selected.value=await ielts.adminPaper(id);editor.value=JSON.stringify(selected.value,null,2);note.value=selected.value.reviewNote||'';confirmed.value=false}catch(e){error.value=e.message}}
async function save(){busy.value=true;error.value='';try{const saved=await ielts.saveDraft(JSON.parse(editor.value));await load();await edit(saved.id);message.value='已保存为新草稿版本，旧版和历史作答保留。'}catch(e){error.value=e.message}finally{busy.value=false}}
async function review(action){busy.value=true;error.value='';try{await ielts.review(selected.value.id,{action,note:note.value});await load();await edit(selected.value.id);message.value=action==='publish'?'已确认复核并发布':'已提交复核'}catch(e){error.value=e.message}finally{busy.value=false}}
async function preview(){try{const a=await ielts.start({paperId:selected.value.id,mode:'practice',requestKey:requestKey()});router.push(`/ielts/attempt/${a.id}`)}catch(e){error.value=e.message}}
async function credits(){busy.value=true;error.value='';try{await ielts.grant(grant);grant.requestKey=requestKey();message.value='邀请额度已发放'}catch(e){error.value=e.message}finally{busy.value=false}}
onMounted(load)
</script>
<template><div class="ielts-page"><IeltsNavigation/><header class="ielts-heading"><div><h1>内容审核与试运营</h1><p>草稿、教师复核、公开发布分别记录，修改生成新版本。</p></div></header><p v-if="error" class="ielts-error" role="alert">{{error}}</p><p class="ielts-status" role="status">{{message}}</p><section class="ielts-section"><h2>内容版本</h2><p v-if="!papers.length" class="muted">尚未导入草稿。部署后运行雅思草稿导入命令。</p><button v-for="p in papers" :key="p.id" class="ielts-list-row" style="width:100%;background:none;border:0;border-bottom:1px solid var(--line);text-align:left" @click="edit(p.id)"><span>{{p.title}} · v{{p.version}}</span><span>{{({draft:'草稿',review:'待复核',published:'已发布'})[p.status]}}</span></button></section><section v-if="selected" class="ielts-section"><h2>{{selected.title}}</h2><p class="ielts-warning">请由有经验的复核人核对题目、标准答案、解析、材料来源，以及实际音频和计时。应用不会自动将 AI 起草内容标为已审核。</p><label>试卷内容（结构化编辑）<textarea v-model="editor" class="ielts-code-editor" aria-label="试卷内容 JSON" :spellcheck="false"></textarea></label><div class="ielts-submit"><button class="btn btn-primary" :disabled="busy" @click="save">另存为新草稿版本</button><button class="btn btn-ghost" @click="preview">预览作答流程</button></div><label>审核人及审核说明<textarea v-model="note" class="ielts-code-editor" style="min-height:100px" aria-label="审核说明" placeholder="填写复核人、已检查项目和结论，至少 10 字"></textarea></label><label><input v-model="confirmed" type="checkbox"> 我确认已完成实际人工复核，材料来源和答案依据可追溯</label><div class="ielts-submit"><button v-if="selected.status==='draft'" class="btn btn-ghost" :disabled="busy||note.trim().length<10" @click="review('review')">提交教师复核</button><button v-if="selected.status==='review'" class="btn btn-primary" :disabled="busy||!confirmed||note.trim().length<10" @click="review('publish')">确认审核并发布</button><span v-if="selected.status==='published'">该版本已公开，修改请另存新版本。</span></div></section><section class="ielts-section"><h2>邀请体验额度</h2><form class="ielts-form" @submit.prevent="credits"><label>用户编号<input v-model.number="grant.userId" type="number" min="1" required></label><label>发放额度<input v-model.number="grant.units" type="number" min="1" max="100000" required></label><div><button class="btn btn-primary" :disabled="busy">发放邀请额度</button></div></form></section></div></template>
